622	// PV: emit ceil(HDVsm/64) 64-col boxes. V box b starts CN*64 elems (one CN-row col-block) apart;
623	// the descriptor leading-byte-offset spans that same col-block (CN*64*2 = CN*128 bytes).
624	template <typename T, int HDV, int CN>
625	__device__ __forceinline__ void pv_boxes(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
626	    constexpr uint32_t LBO = (uint32_t)(CN * 128), BOX = (uint32_t)(CN * 128);
627	    pv_box64<T, 0, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base, LBO, SW_V_SBO, 1));
628	    if constexpr (HDV >= 128) pv_box64<T, 32, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 1*BOX, LBO, SW_V_SBO, 1));
629	    if constexpr (HDV >= 192) pv_box64<T, 64, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 2*BOX, LBO, SW_V_SBO, 1));
630	    if constexpr (HDV >= 256) pv_box64<T, 96, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 3*BOX, LBO, SW_V_SBO, 1));
