632	// First K-block: QK only (s = Q.K^T), HD-generic.
633	template <typename T, int HDt, int CN, int CM = CTA_M>
634	__device__ __forceinline__ void qk_gemm_g(float (&s)[CN/2], uint32_t sQ_wg, uint32_t sK_base) {
635	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
636	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
637	    qk_batch_g<T, HDt, CN, CM>(s, baseA, baseB, 0);
638	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
