641	// Fused QK (next block) + rescale O + PV (current block), HD/HDV/CN-generic. acc_o has HDV/2 regs.
642	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
643	__device__ __forceinline__ void qk_rs_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
644	                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
645	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
646	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
647	    qk_batch_g<T, HD, CN, CM>(s, baseA, baseB, 0);
648	    rescale_o_g(acc_o, sc);
649	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
