651	// Final PV (last block, after the loop), HDV/CN-generic.
652	template <typename T, int HDV, int CN>
653	__device__ __forceinline__ void pv_final_g(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
654	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
655	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
656	    wg_fence_c(acc_o);
