660	// ============================ native fp8 (e4m3) prefill path ============================
661	// QK and PV both run on the fp8 tensor core (2x bf16 throughput). The f32 accumulator layout for
662	// m64n128k32.e4m3 is identical to the bf16 m64n128k16 one, so softmax/mask/epilogue are unchanged.
663	// fp8 1-byte 128B swizzle: 128 fp8 = one 128B row; the 16-byte (16-fp8) chunk is swizzled by row&7.
664	// For hd128/CTA_N=128 every operand tile (Q,K,Vt,P) is a [128-row,128-col] K-major fp8 tile. The
665	// whole recipe (koff8 + LBO16/SBO1024/lt=1 + k32 step=kb*32 + V-transpose + P-in-smem SS-PV) is
666	// validated bit-exact vs a CPU fp8 GEMM in kernels/fp8_probe.cu.
667	__device__ __forceinline__ int koff8(int row, int c) {
668	    return (c >> 7) * (128 * CTA_N) + row * 128 + ((c & 127) ^ ((row & 7) << 4));
669	}
670	constexpr uint32_t SW8_LBO = 16, SW8_SBO = 1024;
671	__device__ __forceinline__ void wg_barrier(int id) {
672	    asm volatile("bar.sync %0, 128;\n" :: "r"(id) : "memory");
673	}
674	// FA3 warp-scheduler ping-pong primitives (mainloop_fwd_sm90_tma_gmma_ws.hpp). A named barrier with
675	// an explicit arrival count: one consumer WG `bar.sync`s it (contributes its 128 threads + blocks)
676	// while the other WG `bar.arrive`s it (contributes 128, no block). With cnt = 256 the syncing WG
677	// unblocks only once the other WG arrives -> the two consumer WGs alternate their wgmma-issue phase
678	// by one step, so while WG_a runs softmax on the SFU, WG_b feeds the tensor core (and vice-versa).
679	__device__ __forceinline__ void nb_sync(int id, int cnt) {
680	    asm volatile("bar.sync %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
681	}
682	__device__ __forceinline__ void nb_arrive(int id, int cnt) {
683	    asm volatile("bar.arrive %0, %1;\n" :: "r"(id), "r"(cnt) : "memory");
684	}
685	// QK: s[64] = Q.K^T (m64n128k32 e4m3 SS over HD; first k-block overwrites, rest accumulate).
686	template <int HDt>
687	__device__ __forceinline__ void qk_fp8_ss(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
688	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
689	#pragma unroll
690	    for (int kb = 0; kb < HDt / 32; ++kb) {
691	        uint32_t off = (uint32_t)(kb * 32);
692	        uint64_t dA = make_smem_desc(sQ_wg + off, SW8_LBO, SW8_SBO, 1);
693	        uint64_t dB = make_smem_desc(sK_base + off, SW8_LBO, SW8_SBO, 1);
694	        int scaleD = (kb == 0) ? 0 : 1;
695	        asm volatile(
696	        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
697	        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
698	        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
699	    }
700	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
701	}
702	// PV: acc_o[64] += P.V (m64n128k32 e4m3 SS over CTA_N keys; A=P[q][key], B=Vt[dv][key]). Always
703	// accumulates (acc_o holds the running online-attention output, pre-scaled by the softmax correction).
704	__device__ __forceinline__ void pv_fp8_ss(float (&acc_o)[64], uint32_t sP_wg, uint32_t sV_base) {
705	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
706	#pragma unroll
707	    for (int kb = 0; kb < CTA_N / 32; ++kb) {
708	        uint32_t off = (uint32_t)(kb * 32);
709	        uint64_t dA = make_smem_desc(sP_wg + off, SW8_LBO, SW8_SBO, 1);
710	        uint64_t dB = make_smem_desc(sV_base + off, SW8_LBO, SW8_SBO, 1);
711	        asm volatile(
712	        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
713	        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
714	        : PF_OUT64(acc_o) : "l"(dA),"l"(dB),"r"(1),"n"(1),"n"(1));
715	    }
716	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
717	}
718	// Scatter softmax probabilities (in the C-accumulator layout) into the K-major fp8 P tile sP.
719	// Two adjacent key-cols share a byte pair => one st.shared.u16 (koff8 is even at col=8c+2tg).
720	__device__ __forceinline__ void scatter_P_fp8(const float (&s)[64], uint32_t sP_wg_addr,
721	                                              int warp, int group, int tg) {
722	#pragma unroll
723	    for (int c = 0; c < CTA_N / 8; ++c)
724	#pragma unroll
725	        for (int r = 0; r < 2; ++r) {
726	            int row = warp * 16 + group + r * 8;
727	            int col = 8 * c + 2 * tg;
728	            __nv_fp8_e4m3 a(s[c*4+r*2+0]), b(s[c*4+r*2+1]);
729	            uint16_t packed = (uint16_t)a.__x | ((uint16_t)b.__x << 8);
730	            uint32_t dst = sP_wg_addr + (uint32_t)koff8(row, col);
731	            asm volatile("st.shared.u16 [%0], %1;\n" :: "r"(dst), "h"(packed) : "memory");
732	        }
733	}
734	// cp.async gather (fp8): the producer issues raw 16-byte copies and races STAGES ahead instead of
735	// blocking on each LDG (a synchronous uint4 gather exposes ~56% long_scoreboard at 1 CTA/SM since
736	// there is no other resident CTA to hide it). Completion is tied to an mbarrier via
737	// cp_async_mbar_arrive. Invalid rows (key>=seqlen_k
738	// or padded q) are zeroed synchronously: masked-out keys must still be finite (P=0 * V; a stale fp8
739	// NaN would make 0*NaN=NaN). cp.async can't convert/transpose, so K/Q go straight to the swizzled
740	// tile while V lands in a PLAIN [key][dv] staging tile that a later in-smem pass transposes.
741	template <int HDt>
742	__device__ __forceinline__ void gather_row_k8_cp(__nv_fp8_e4m3* sbase, uint32_t sbase_addr, int row,
743	                                                 const __nv_fp8_e4m3* src, bool valid) {
744	#pragma unroll
745	    for (int c16 = 0; c16 < HDt / 16; ++c16) {
746	        int o = koff8(row, c16 * 16);
747	        if (valid) cp_async_16(sbase_addr + (uint32_t)o, src + c16 * 16);
748	        else       *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0);
749	    }
750	}
751	template <int HDt>
752	__device__ __forceinline__ void gather_row_plain8_cp(__nv_fp8_e4m3* sbase, uint32_t sbase_addr, int row,
753	                                                     const __nv_fp8_e4m3* src, bool valid) {
754	#pragma unroll
755	    for (int c16 = 0; c16 < HDt / 16; ++c16) {
756	        int o = row * HDt + c16 * 16;
757	        if (valid) cp_async_16(sbase_addr + (uint32_t)o, src + c16 * 16);
758	        else       *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0);
759	    }
760	}
761	// Transpose one key column of the PLAIN [key][dv] staging tile into the swizzled K-major sVt[dv][key]
762	// (smem->smem; the global load latency is now hidden by cp.async, this pass only touches smem).
763	template <int HDVt>
764	__device__ __forceinline__ void transpose_v_smem8(__nv_fp8_e4m3* sVt, const __nv_fp8_e4m3* sVst, int key) {
765	#pragma unroll
766	    for (int c16 = 0; c16 < HDVt / 16; ++c16) {
767	        uint4 chunk = *reinterpret_cast<const uint4*>(sVst + key * HDVt + c16 * 16);
768	        const __nv_fp8_e4m3* cv = reinterpret_cast<const __nv_fp8_e4m3*>(&chunk);
769	#pragma unroll
770	        for (int e = 0; e < 16; ++e) sVt[koff8(c16 * 16 + e, key)] = cv[e];
771	    }
772	}
