776	// Gather one row (HDt elems) of K-major data from gmem into the swizzled smem tile (16-bit TC), OR
777	// zero it. TIn is the gmem element type: when TIn==TC (bf16/fp16) it is a raw 16-byte copy (cp.async
778	// or store); when TIn is fp8-e4m3 each 8-elem chunk is loaded, converted to TC (bf16) and stored
779	// (TMA/cp.async can't convert ⇒ fp8 always takes the synchronous convert-store path).
780	template <typename TIn, typename TC, int HDt, int ROWS = CTA_N>
781	__device__ __forceinline__ void gather_row_k(TC* sbase, uint32_t sbase_addr, int row,
782	                                             const TIn* src, bool valid) {
783	#pragma unroll
784	    for (int c8 = 0; c8 < HDt / 8; ++c8) {
785	        int o = koffR<ROWS>(row, c8 * 8);
786	        if (!valid) { *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0); continue; }
787	        if constexpr (std::is_same<TIn, TC>::value) {
788	#if PF_CPASYNC
789	            cp_async_16(sbase_addr + (uint32_t)(o * 2), src + c8 * 8);
790	#else
791	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(src + c8 * 8);
792	#endif
793	        } else {
794	            TC tmp[8];
795	#pragma unroll
796	            for (int e = 0; e < 8; ++e) tmp[e] = from_float<TC>(to_float<TIn>(src[c8 * 8 + e]));
797	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(tmp);
798	        }
799	    }

