102	// For SM80, convert acc_layout from (MMA=4, MMA_M, MMA_N) to (nrow=(2, MMA_M), ncol=(2, MMA_N))
103	// For SM90, convert acc_layout from ((2, 2, V), MMA_M, MMA_N) to (nrow=(2, MMA_M), ncol=(2, V, MMA_N))
104	template<bool Transposed=false, typename Layout0>
105	CUTLASS_DEVICE auto convert_layout_acc_rowcol(Layout0 acc_layout) {
106	    if constexpr (decltype(rank<0>(acc_layout))::value == 3) {  // SM90
107	        static_assert(decltype(size<0, 0>(acc_layout))::value == 2);
108	        static_assert(decltype(size<0, 1>(acc_layout))::value == 2);
109	        static_assert(decltype(rank(acc_layout))::value == 3);
110	        auto l = acc_layout;
111	        if constexpr (!Transposed) {
112	            return make_layout(make_layout(get<0, 1>(l), get<1>(l)), make_layout(get<0, 0>(l), get<0, 2>(l), get<2>(l)));
113	        } else {
114	             return make_layout(make_layout(get<0, 0>(l), get<0, 2>(l), get<2>(l)), make_layout(get<0, 1>(l), get<1>(l)));
115	        }
116	
117	    } else {  // SM80
118	        static_assert(decltype(size<0>(acc_layout))::value == 4);
119	        static_assert(decltype(rank(acc_layout))::value == 3);
120	        auto l = logical_divide(acc_layout, Shape<_2>{});  // ((2, 2), MMA_M, MMA_N)
121	        if constexpr (!Transposed) {
122	            return make_layout(make_layout(get<0, 1>(l), get<1>(l)), make_layout(get<0, 0>(l), get<2>(l)));
123	        } else {
124	            return make_layout(make_layout(get<0, 0>(l), get<2>(l)), make_layout(get<0, 1>(l), get<1>(l)));
