131	// For SM80, convert acc_layout from (MMA=4, MMA_M, MMA_N) to ((4, 2), MMA_M, MMA_N / 2)
132	// if using m16n8k16, or to (4, MMA_M, MMA_N) if using m16n8k8.
133	// For SM90, FP16/BF16, convert acc_layout from ((2, 2, N / 8), MMA_M, MMA_N) to ((2, 2, 2), MMA_M, (N / 16, MMA_N))
134	// For SM90, FP8, convert acc_layout from ((2, 2, N / 8), MMA_M, MMA_N) to ((4, 2, 2), MMA_M, (N / 32, MMA_N))
135	template<typename MMA_Traits, typename Layout0>
136	CUTLASS_DEVICE auto convert_layout_acc_Aregs(Layout0 acc_layout) {
137	    using X = Underscore;
138	    if constexpr (decltype(rank<0>(acc_layout))::value == 3) {  // SM90
139	        static_assert(decltype(size<0, 0>(acc_layout))::value == 2);
140	        static_assert(decltype(size<0, 1>(acc_layout))::value == 2);
141	        static_assert(decltype(rank(acc_layout))::value == 3);
142	        static_assert(decltype(rank(get<0>(acc_layout)))::value == 3);
143	        if constexpr (sizeof(typename MMA_Traits::ValTypeA) == 2) {
144	            auto l = logical_divide(get<0, 2>(acc_layout), Tile<_2>{});  // ((2, N / 16))
145	            return make_layout(make_layout(get<0, 0>(acc_layout), get<0, 1>(acc_layout), get<0, 0>(l)), get<1>(acc_layout), coalesce(make_layout(get<0, 1>(l), get<2>(acc_layout))));
146	        } else {
147	            static_assert(sizeof(typename MMA_Traits::ValTypeA) == 1);
148	            static_assert(decltype(stride<0, 0>(acc_layout))::value == 1);
149	            static_assert(decltype(stride<0, 1>(acc_layout))::value == 2);
150	            auto l = logical_divide(get<0, 2>(acc_layout), Tile<Layout<Shape<_2, _2>>>{});  // (((2, 2), N / 32))
151	            // This combines the first two modes (<0, 0> and <0, 1>) into one mode.
152	            // Will require register shuffling later to be correct.
153	            return make_layout(make_layout(Layout<_4>{}, get<0, 0, 0>(l), get<0, 0, 1>(l)),
154	                               get<1>(acc_layout),
155	                               coalesce(make_layout(get<0, 1>(l), get<2>(acc_layout))));  // ((4, 2, 2), MMA_M, N / 32 * MMA_N)
156	            // This combination is right but doesn't work with register shuffling.
157	            // return make_layout(make_layout(coalesce(make_layout(get<0, 0>(acc_layout), get<0, 0, 0>(l))), get<0, 1>(acc_layout), get<0, 0, 1>(l)),
158	            //                    get<1>(acc_layout),
159	            //                    coalesce(make_layout(get<0, 1>(l), get<2>(acc_layout))));
160	        }
161	    } else {  // SM80
162	        static_assert(decltype(size<0>(acc_layout))::value == 4);
163	        static_assert(decltype(rank(acc_layout))::value == 3);
164	        constexpr int mma_shape_K = get<2>(typename MMA_Traits::Shape_MNK{});
165	        static_assert(mma_shape_K == 8 || mma_shape_K == 16);
166	        if constexpr (mma_shape_K == 8) {
167	            return acc_layout;
168	        } else {
169	            auto l = logical_divide(acc_layout, Shape<X, X, _2>{});  // (4, MMA_M, (2, MMA_N / 2)))
170	            return make_layout(make_layout(get<0>(l), get<2, 0>(l)), get<1>(l), get<2, 1>(l));
171	        }
172	    }
173	};
