208	// Blocks until all but N previous cp.async.commit_group operations have committed.
209	// This differs from cute::cp_async_wait in that when N = 0 we don't call cp.async.wait_all
210	// (which is equivalent to commit_group then wait_group 0).
211	// Instead we just call cp.async.wait_group 0, which is slightly faster.
212	// https://github.com/NVIDIA/cutlass/blob/master/include/cute/arch/copy_sm80.hpp#L113
213	template <int N>
214	CUTE_HOST_DEVICE
215	void cp_async_wait() {
216	#if defined(CUTE_ARCH_CP_ASYNC_SM80_ENABLED)
217	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
218	#endif
219	}
