332	template<bool A_in_regs=false, bool B_in_regs=false, bool SwapAB=false,
333	         typename Tensor0, typename Tensor1,
334	         typename Tensor2, typename Tensor3, typename Tensor4,
335	         typename TiledMma, typename TiledCopyA, typename TiledCopyB,
336	         typename ThrCopyA, typename ThrCopyB, typename Hook>
337	CUTLASS_DEVICE void gemm_sm80(Tensor0 &acc, Tensor1 &tCrA, Tensor2 &tCrB, Tensor3 const& tCsA,
338	                              Tensor4 const& tCsB, TiledMma tiled_mma,
339	                              TiledCopyA smem_tiled_copy_A, TiledCopyB smem_tiled_copy_B,
340	                              ThrCopyA smem_thr_copy_A, ThrCopyB smem_thr_copy_B, Hook fn) {
341	    if constexpr (SwapAB) {
342	        gemm_sm80<B_in_regs, A_in_regs>(acc, tCrB, tCrA, tCsB, tCsA, tiled_mma, smem_tiled_copy_B, smem_tiled_copy_A, smem_thr_copy_B, smem_thr_copy_A, fn);
343	    } else {
344	        CUTE_STATIC_ASSERT_V(size<1>(tCrA) == size<1>(acc));                     // MMA_M
345	        CUTE_STATIC_ASSERT_V(size<1>(tCrB) == size<2>(acc));                     // MMA_N
346	        CUTE_STATIC_ASSERT_V(size<2>(tCrA) == size<2>(tCrB));                     // MMA_K
347	        Tensor tCrA_copy_view = smem_thr_copy_A.retile_D(tCrA);
348	        CUTE_STATIC_ASSERT_V(size<1>(tCsA) == size<1>(tCrA_copy_view));            // M
349	        Tensor tCrB_copy_view = smem_thr_copy_B.retile_D(tCrB);
350	        CUTE_STATIC_ASSERT_V(size<1>(tCsB) == size<1>(tCrB_copy_view));            // N
351	        if (!A_in_regs) { cute::copy(smem_tiled_copy_A, tCsA(_, _, _0{}), tCrA_copy_view(_, _, _0{})); }
352	        if (!B_in_regs) { cute::copy(smem_tiled_copy_B, tCsB(_, _, _0{}), tCrB_copy_view(_, _, _0{})); }
353	        #pragma unroll
354	        for (int i = 0; i < size<2>(tCrA); ++i) {
355	            if (i < size<2>(tCrA) - 1) {
356	                if (!A_in_regs) { cute::copy(smem_tiled_copy_A, tCsA(_, _, i + 1), tCrA_copy_view(_, _, i + 1)); }
357	                if (!B_in_regs) { cute::copy(smem_tiled_copy_B, tCsB(_, _, i + 1), tCrB_copy_view(_, _, i + 1)); }
358	            }
359	            if constexpr (!std::is_same_v<Hook, std::nullptr_t>) {
360	                if (i == 0) { fn(); }
361	            }
362	            cute::gemm(tiled_mma, tCrA(_, _, i), tCrB(_, _, i), acc);
363	        }
364	    }
365	}
