391	template <bool zero_init=false, typename Atom, typename TA, typename TB, typename TC>
392	CUTLASS_DEVICE void gemm_sm100(Atom& atom, TA const& tA, TB const& tB, TC&& tC) {
393	    static constexpr int rA = decltype(rank(tA))::value;
394	    static constexpr int rB = decltype(rank(tB))::value;
395	    static constexpr int rC = decltype(rank(tC))::value;
396	    static_assert(rA == 3 && rB == 3 && rC == 3);
397	
398	    if constexpr (zero_init) { atom.accumulate_ = decltype(atom.accumulate_)::Zero; }
399	    CUTLASS_PRAGMA_UNROLL
400	    for (int k_block = 0; k_block < size<2>(tA); k_block++) {
401	        cute::gemm(atom, tA(_,_,k_block), tB(_,_,k_block), tC);
402	        atom.accumulate_ = decltype(atom.accumulate_)::One;
403	    }
404	}
