598	
599	template <typename Fragment>
600	CUTLASS_DEVICE void permute_output_fp8_Vcolmajor(Fragment &frag) {
601	    // frag has shape ((2, 2, N / 8), MMA_M, MMA_N), each element is 16 bits
602	    static_assert(decltype(size<0, 0>(frag))::value == 2);
603	    static_assert(decltype(size<0, 1>(frag))::value == 2);
604	    static_assert(decltype(stride<0, 0>(frag))::value == 1);
605	    static_assert(sizeof(typename Fragment::value_type) == 2 || sizeof(typename Fragment::value_type) == 4);
606	
607	    int quad_idx = threadIdx.x % 4;
608	    bool lane_03 = quad_idx == 0 || quad_idx == 3;
609	
610	    static constexpr int upper_map[4] = {0, 2, 3, 1};
611	    // static constexpr int lower_map[4] = {2, 0, 1, 3};
612	
613	    // if (blockIdx.x == 0 && threadIdx.x == 128) { print_tensor(frag); }
614	    using type2 = std::conditional_t<sizeof(typename Fragment::value_type) == 2, uint32_t, uint64_t>;
615	    Tensor frag_2 = group_modes<1, 3>(recast<type2>(frag));  // ((1, 2, N / 8), (MMA_M, MMA_N))
616	    // if (blockIdx.x == 0 && threadIdx.x == 128) { print(frag); printf("\n"); print(frag_2); }
617	    #pragma unroll
618	    for (int mi = 0; mi < size<1>(frag_2); ++mi) {
619	        #pragma unroll
620	        for (int j = 0; j < size<0, 1>(frag_2); ++j) {
621	            #pragma unroll
622	            for (int i = 0; i < size<0, 2>(frag_2) / 2; ++i) {
623	                type2 upper = frag_2(make_coord(_0{}, j, 2 * i), mi);
624	                type2 lower = frag_2(make_coord(_0{}, j, 2 * i + 1), mi);
625	                type2 upper0 = lane_03 ? upper : lower;
626	                type2 lower0 = lane_03 ? lower : upper;
627	                upper0 = __shfl_sync(uint32_t(-1), upper0, upper_map[quad_idx], 4);
628	                // lower0 = __shfl_sync(uint32_t(-1), lower0, lower_map[quad_idx], 4);
629	                lower0 = __shfl_sync(uint32_t(-1), lower0, upper_map[quad_idx] ^ 2, 4);
630	                frag_2(make_coord(_0{}, j, 2 * i), mi) = lane_03 ? upper0 : lower0;
631	                frag_2(make_coord(_0{}, j, 2 * i + 1), mi) = lane_03 ? lower0 : upper0;
632	            }
633	        }
634	    }
635	    // if (blockIdx.x == 0 && threadIdx.x == 128) { print_tensor(frag); }
