493	__device__ __forceinline__ void qk_batch_cute(float (&s)[64], uint64_t baseA, uint64_t baseB, int p0) {
494	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
495	#pragma unroll
496	    for (int kb = 0; kb < HD / 16; ++kb) {
497	        uint64_t dA = desc_add(baseA, (uint32_t)qk_doff(kb));
498	        uint64_t dB = desc_add(baseB, (uint32_t)qk_doff(kb));
499	        int scaleD = (kb == 0) ? p0 : 1;
