501	        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
502	        "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " PF_ACC64 ",%64,%65,p,%67,%68,%69,%70;\n}\n"
503	        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
504	    }
505	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
506	}
