823	// ---- continuous-ring work-item decode (shared by the persistent producer & consumers) ----
824	// One linear work index -> (bi, hk, m_block) + the per-tile bounds. Producer and consumers call this
825	// with the SAME work index so they agree on n_cnt (and thus the global ring counter g advances in
826	// lock-step). Mirrors the per-tile prefill_kernel coordinate/bounds math, minus split-KV (prefill
827	// runs num_splits==1). m_block is LPT-reversed (largest causal tile first) for static-strided balance.
828	struct PfTile {
829	    bool valid;
830	    int q0, hk, seqlen_q, seqlen_k, Mrows, row0, delta, n_lo, n_cnt;
831	    float sc_eff, s2, vd;
832	};
833	template <int CN, int CM, bool EXTRA>
834	__device__ __forceinline__ PfTile pf_work(
835	        int work, int tiles_m, int hkv, int rep,
836	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
837	        int causal, int win_l, int win_r, float scale,
838	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
839	        const float* __restrict__ v_descale, int ds_b, int ds_h) {
840	    PfTile t; t.valid = false;
841	    const int hb = tiles_m * hkv;
842	    const int bi = work / hb;
843	    const int rem = work - bi * hb;
844	    t.hk = rem / tiles_m;
845	    const int m_block = (tiles_m - 1) - (rem - t.hk * tiles_m);   // LPT: largest causal tile first
846	    t.q0 = cu_q[bi];
847	    t.seqlen_q = cu_q[bi + 1] - t.q0;
848	    t.seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
849	    t.Mrows = t.seqlen_q * rep;
850	    t.row0 = m_block * CM;
851	    if (t.row0 >= t.Mrows || t.seqlen_k <= 0) return t;            // padded m_block / empty seq
852	    t.delta = t.seqlen_k - t.seqlen_q;
853	    const long ds_idx = (long)bi * ds_b + (long)t.hk * ds_h;
854	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
855	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
856	    t.vd = v_descale ? v_descale[ds_idx] : 1.f;
857	    t.sc_eff = scale * qd * kd;
858	    t.s2 = t.sc_eff * float(M_LOG2E);
859	    const int top = (t.row0 + CM - 1 < t.Mrows - 1) ? (t.row0 + CM - 1) : (t.Mrows - 1);
860	    const int qabs_max = (top / rep) + t.delta;
861	    int n_max = causal ? ((qabs_max + 1 + CN - 1) / CN) : ((t.seqlen_k + CN - 1) / CN);
862	    int n_beg = 0;
863	    if constexpr (EXTRA) {
864	        if (win_l >= 0) { int lo = (t.row0 / rep) + t.delta - win_l; if (lo > 0) n_beg = lo / CN; }
865	        if (!causal && win_r >= 0) { int tt = (qabs_max + win_r) / CN + 1; if (tt < n_max) n_max = tt; }
866	    }
867	    if (n_beg >= n_max) return t;                                  // fully masked
868	    t.n_lo = n_beg; t.n_cnt = n_max - n_beg;
869	    t.valid = true;
870	    return t;
871	}
